// ── Focus management ─────────────────────────────────────────────────────────

/** Move keyboard focus to the first focusable element within a container. */
export const focusFirst = (container: HTMLElement | null): void => {
  if (!container) return;
  const el = container.querySelector<HTMLElement>(
    'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
  );
  el?.focus();
};

/** Trap keyboard focus inside a container (dialogs, modals). Returns cleanup. */
export const trapFocus = (container: HTMLElement): () => void => {
  const focusable = Array.from(
    container.querySelectorAll<HTMLElement>(
      'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
    )
  );
  if (focusable.length === 0) return () => {};
  const first = focusable[0];
  const last = focusable[focusable.length - 1];

  const handler = (e: KeyboardEvent) => {
    if (e.key !== 'Tab') return;
    if (e.shiftKey) {
      if (document.activeElement === first) { e.preventDefault(); last.focus(); }
    } else {
      if (document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
  };
  container.addEventListener('keydown', handler);
  return () => container.removeEventListener('keydown', handler);
};

/** Restore focus to a previously focused element (e.g. when modal closes). */
export const useFocusRestore = () => {
  let saved: HTMLElement | null = null;
  return {
    save: () => { saved = document.activeElement as HTMLElement; },
    restore: () => { saved?.focus(); saved = null; },
  };
};

// ── Live region announcements (WCAG 4.1.3) ───────────────────────────────────

let liveRegion: HTMLElement | null = null;

const ensureLiveRegion = (): HTMLElement => {
  if (!liveRegion) {
    liveRegion = document.createElement('div');
    liveRegion.setAttribute('aria-live', 'polite');
    liveRegion.setAttribute('aria-atomic', 'true');
    liveRegion.style.cssText = 'position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap';
    document.body.appendChild(liveRegion);
  }
  return liveRegion;
};

/** Announce a message to screen readers via aria-live polite. */
export const announce = (message: string, priority: 'polite' | 'assertive' = 'polite'): void => {
  const el = ensureLiveRegion();
  el.setAttribute('aria-live', priority);
  // Clear then set to ensure re-announcement of the same message
  el.textContent = '';
  requestAnimationFrame(() => { el.textContent = message; });
};

// ── Skip link (WCAG 2.4.1) ───────────────────────────────────────────────────

/**
 * Inject a "Skip to main content" link as the first focusable element.
 * Call once in your root layout.
 * @example  injectSkipLink('#main-content')
 */
export const injectSkipLink = (targetId: string, label = 'Skip to main content'): void => {
  if (typeof document === 'undefined') return;
  if (document.getElementById('ang-skip-link')) return;
  const link = document.createElement('a');
  link.id = 'ang-skip-link';
  link.href = targetId;
  link.textContent = label;
  link.style.cssText = [
    'position:fixed', 'top:-40px', 'left:0', 'z-index:9999',
    'padding:8px 16px', 'background:#000', 'color:#fff',
    'border-radius:0 0 4px 0', 'font-size:14px', 'transition:top 0.2s',
  ].join(';');
  link.addEventListener('focus', () => { link.style.top = '0'; });
  link.addEventListener('blur', () => { link.style.top = '-40px'; });
  document.body.insertBefore(link, document.body.firstChild);
};

// ── ARIA helpers ──────────────────────────────────────────────────────────────

/** Generate a stable aria-describedby id for a field's error message. */
export const errorId = (fieldName: string): string => `${fieldName}-error`;

/** Generate a stable aria-labelledby id for a field's label. */
export const labelId = (fieldName: string): string => `${fieldName}-label`;

/** Props to spread on an input with validation state (WCAG 1.3.1, 4.1.3). */
export const ariaFieldProps = (fieldName: string, hasError: boolean) => ({
  id: fieldName,
  'aria-invalid': hasError || undefined,
  'aria-describedby': hasError ? errorId(fieldName) : undefined,
  'aria-labelledby': labelId(fieldName),
});

/** Props for the error message element paired with a field. */
export const ariaErrorProps = (fieldName: string) => ({
  id: errorId(fieldName),
  role: 'alert' as const,
  'aria-live': 'polite' as const,
});

// ── Colour contrast check (WCAG 1.4.3 AA = 4.5:1) ───────────────────────────

/** Relative luminance per WCAG 2.1 formula. Input: hex string e.g. "#ffffff". */
export const relativeLuminance = (hex: string): number => {
  const rgb = hex.replace('#', '').match(/.{2}/g)!.map((c) => {
    const v = parseInt(c, 16) / 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
};

/** Contrast ratio between two hex colours. AA requires ≥ 4.5 for normal text. */
export const contrastRatio = (hex1: string, hex2: string): number => {
  const l1 = relativeLuminance(hex1);
  const l2 = relativeLuminance(hex2);
  const [light, dark] = l1 > l2 ? [l1, l2] : [l2, l1];
  return (light + 0.05) / (dark + 0.05);
};

/** Returns true when the pair meets WCAG 2.1 AA (4.5:1 for normal text). */
export const meetsWCAG_AA = (fg: string, bg: string): boolean =>
  contrastRatio(fg, bg) >= 4.5;
